SET NAMES utf8mb4;
SET @uk = (SELECT language_id FROM oc_language WHERE code = 'uk-ua' LIMIT 1);
UPDATE oc_setting SET `value` = JSON_SET(`value`, CONCAT('$."', @uk, '"'), 'Безкоштовна доставка від 60 $ · 30 днів на повернення') WHERE store_id = 0 AND `key` = 'mintcart_announcement_texts' AND @uk IS NOT NULL;
DELETE FROM oc_banner_image WHERE banner_id = 8 AND language_id = @uk;
