REPLACE INTO oc_mc_block_description (block_id, language_id, content_json) SELECT block_id, @uk, '{"title": "Купуйте за категоріями"}' FROM oc_mc_block WHERE page_id = (SELECT page_id FROM oc_mc_page WHERE code = 'home') AND type = 'categories' AND @uk IS NOT NULL;
