REPLACE INTO oc_mc_block_description (block_id, language_id, content_json) SELECT block_id, @uk, '{"title": "Речі, створені для користування", "body": "<p>Ми обираємо невелику кількість добре зроблених речей для дому й тримаємо їх у наявності. Кераміка з невеликих майстерень, масив дуба, льон і соєвий віск — без зайвого.</p><p>Кожен товар сфотографований таким, яким він є, а кожне замовлення відправляється в упаковці, що переробляється.</p>", "image_alt": "Наша колекція для дому"}' FROM oc_mc_block WHERE page_id = (SELECT page_id FROM oc_mc_page WHERE code = 'home') AND type = 'text-image' AND @uk IS NOT NULL;
REPLACE INTO oc_mc_block_description (block_id, language_id, content_json) SELECT block_id, @uk, '{"title": "Що кажуть покупці"}' FROM oc_mc_block WHERE page_id = (SELECT page_id FROM oc_mc_page WHERE code = 'home') AND type = 'testimonials' AND @uk IS NOT NULL;
REPLACE INTO oc_mc_block_description (block_id, language_id, content_json) SELECT block_id, @uk, '{"title": "Питання та відповіді", "items": [{"question": "Скільки триває доставка?", "answer": "Зазвичай 1–3 робочі дні по країні. Номер відстеження ви отримаєте електронною поштою."}, {"question": "Чи можна повернути товар?", "answer": "Так, протягом 30 днів, якщо він не використовувався. Напишіть нам, і ми організуємо забір."}, {"question": "Які способи оплати ви приймаєте?", "answer": "Банківські картки, банківський переказ і накладений платіж."}]}' FROM oc_mc_block WHERE page_id = (SELECT page_id FROM oc_mc_page WHERE code = 'home') AND type = 'faq' AND @uk IS NOT NULL;
REPLACE INTO oc_mc_block_description (block_id, language_id, content_json) SELECT block_id, @uk, '{"title": "Не знаєте, що обрати?", "text": "Розкажіть про вашу кімнату, і ми підберемо кілька речей, які добре поєднуються.", "cta_label": "Зв’язатися з нами", "cta_url": "index.php?route=information/contact"}' FROM oc_mc_block WHERE page_id = (SELECT page_id FROM oc_mc_page WHERE code = 'home') AND type = 'cta' AND @uk IS NOT NULL;
INSERT INTO oc_banner_image (banner_id, language_id, title, link, image, sort_order) SELECT banner_id, @uk, title, link, image, sort_order FROM oc_banner_image WHERE banner_id = 8 AND language_id = 1 AND @uk IS NOT NULL;
